#!/bin/sh
# Generated by seaworthy: acme-agent, rpm, before unpack. See seaworthy::scripts.
set -e
systemd_running() { [ -d /run/systemd/system ]; }
has_systemctl() { command -v systemctl >/dev/null 2>&1; }
try() { "$@" || echo "acme-agent: warning: '$*' failed (exit $?); continuing" >&2; }
# shellcheck disable=SC3067 # test -O: dash, bash and busybox all have it
marker_dir_ok() { [ -d /run/seaworthy ] && [ ! -L /run/seaworthy ] && [ -O /run/seaworthy ]; }
action=none
case "${1:-}" in
  1) action=install ;;
  [2-9]|[1-9][0-9]*) action=upgrade ;;
esac
if [ "$action" = install ] || [ "$action" = upgrade ]; then
  if [ -d /run ] && { [ -e /run/seaworthy ] || mkdir -m 0700 /run/seaworthy; } && marker_dir_ok; then
    : > /run/seaworthy/acme-agent.new-units
    units="AcmeAgent-update.path AcmeAgent.service"
    for unit in $units; do
      if [ ! -e /usr/lib/systemd/system/"$unit" ]; then echo "$unit" >> /run/seaworthy/acme-agent.new-units; fi
    done
  fi
fi
